#!/bin/bash

# Dynamically set listener port in config.yml if generated by EaglerXBungee
if [ -f "config.yml" ]; then
  sed -i "s/host: 0.0.0.0:[0-9]*/host: 0.0.0.0:${PORT:-8080}/g" config.yml
fi

# Run Java with restricted RAM (400MB max) to avoid Render out-of-memory crashes
exec java -Xmx400M -Xms256M -jar server.jar nogui
